<script setup lang="ts">
// the game calls for dice: press, or throw your own and say what fell
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { app, gs, act, close, setDice, game, stageThrow } from '../session'
import { sfx } from '../audio'
import type { Call, CallGroup } from '../rules/state'
import { signed } from '../rules/base'
import Die from './Die.vue'
const call = computed(() => (gs.value?.calls ?? []).find(c => c.who === app.seat) ?? null); const others = computed(() => (gs.value?.calls ?? []).filter(c => c.who !== app.seat)); const busy = ref(false), shown = ref<{ c: Call; v: number[][] } | null>(null), flick = ref(0); let ft: any, st: any
const KIND: Record<string, string> = { hit: 'Attack', dmg: 'Damage', save: 'Saving throw', check: 'Check', init: 'Initiative', death: 'Death save', heal: 'Healing', luck: 'One more' }
const cur = computed<Call | null>(() => shown.value?.c ?? call.value); const g0 = computed(() => cur.value?.groups[0]); const title = computed(() => { const g = g0.value; if (!g) return ''; if (g.kind === 'hit') return `${g.label}${g.note ? ' against ' + g.note : ''}`; if (g.kind === 'dmg') return `Damage${g.note ? ' to ' + g.note : ''}`; if (g.kind === 'save') return g.label; if (g.kind === 'check') return g.label; if (g.kind === 'init') return 'Initiative'; if (g.kind === 'death') return 'Death save'; return g.label }); const why = computed(() => { const g = g0.value; if (!g) return ''; if (g.kind === 'save') return g.note ? `against ${g.note}` : ''; if (g.kind === 'check' && g.note) return `to ${g.note}`; if (g.kind === 'death') return '10 or more to hold on'; if (g.kind === 'init') return 'Who moves first?'; return '' })
const expr = (g: CallGroup) => { const by = new Map<number, number>(); for (const d of g.dice) by.set(d, (by.get(d) ?? 0) + 1); return [...by].map(([d, n]) => `${n > 1 || d !== 20 ? n : ''}d${d}`).join(' + ') }; const keep = (g: CallGroup, v: number[]) => { if (!g.adv || g.dice.filter(d => d === 20).length < 2) return v.map(() => true); const a = v[0], b = v[1]; const k = g.adv > 0 ? (a >= b ? 0 : 1) : (a <= b ? 0 : 1); return v.map((_, i) => i > 1 || i === k) }; const tot = (g: CallGroup, v: number[]) => v.reduce((a, x, i) => a + (keep(g, v)[i] ? x : 0), 0) + g.mod
const typing = computed(() => app.prefs.dice === 'type' && gs.value?.set.handDice !== false); const vals = reactive<Record<string, (number | null)[]>>({}); const one = (g: CallGroup) => g.kind === 'dmg' || g.kind === 'heal' ? g.dice.length > 2 : false; watch(() => call.value?.id, () => { for (const k in vals) delete vals[k]; if (call.value) { call.value.groups.forEach((g, i) => { vals[i] = one(g) ? [null] : g.dice.map(() => null) }); sfx.chime(); game.value?.input.unlock(); if (app.modal && !['amend', 'settings', 'level'].includes(app.modal)) close() } }, { immediate: true }); const ready = computed(() => !!call.value && call.value.groups.every((g, i) => (vals[i] ?? []).every((v, j) => { const lo = one(g) ? g.dice.length : 1, hi = one(g) ? g.dice.reduce((a, b) => a + b, 0) : g.dice[j]; return Number.isInteger(v) && v! >= lo && v! <= hi })))
const send = async (hand: boolean) => { const c = call.value; if (!c || busy.value) return; busy.value = true; const m: any = { k: 'roll', id: c.id }; if (hand) { m.v = c.groups.map((g, i) => one(g) ? null : vals[i]); m.sum = c.groups.map((g, i) => one(g) ? vals[i][0] : null) } sfx.dice(); const r: any = await act(m, app.seat); busy.value = false; if (r.ok && r.v) { shown.value = { c, v: r.v }; if (!hand) { flick.value = 1; clearInterval(ft); ft = setInterval(() => { flick.value++; if (flick.value > 9) { clearInterval(ft); flick.value = 0 } }, 45) } clearTimeout(st); st = setTimeout(() => shown.value = null, hand ? 900 : 1500) } }
const back = () => { const c = call.value; if (c) void act({ k: 'roll', id: c.id, cancel: true }, app.seat) }; const face = (i: number, j: number, d: number) => shown.value ? (flick.value ? 1 + ((flick.value * 7 + i * 5 + j * 3) % d) : shown.value.v[i]?.[j] ?? null) : null
const key = (e: KeyboardEvent) => { if (!call.value || shown.value || app.modal || ['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) return; if ((e.code === 'Space' || e.code === 'Enter') && !typing.value) { e.preventDefault(); e.stopImmediatePropagation(); void send(false) } }; onMounted(() => addEventListener('keydown', key, true)); onBeforeUnmount(() => { removeEventListener('keydown', key, true); clearInterval(ft); clearTimeout(st) })
const nm = (id: string) => gs.value?.chars[id]?.name ?? 'Someone'
</script>
<template><div class="rc"><div v-if="others.length" class="ot"><span v-for="c in others" :key="c.id">{{ nm(c.who) }} is throwing {{ (KIND[c.groups[0].kind] ?? 'dice').toLowerCase() }}<button v-if="app.hosting" class="btn sm" @click="stageThrow(c.id)">Throw for them</button></span></div>
  <section v-if="cur" class="card paper" :class="{ done: shown }" role="dialog" :aria-label="title"><header><small>{{ KIND[g0!.kind] }}</small><h3>{{ title }}</h3><p v-if="why || g0!.adv || g0!.dc">{{ why }}<template v-if="g0!.adv">{{ why ? ', ' : '' }}{{ g0!.adv > 0 ? 'with advantage' : 'with disadvantage' }}</template></p><b v-if="g0!.dc && g0!.kind !== 'hit'" class="dc">{{ g0!.dc }}<i>to beat</i></b></header>
    <div v-for="(g, i) in cur.groups" :key="i" class="grp"><span v-if="cur.groups.length > 1" class="gl">{{ g.label }}</span><template v-if="typing && !shown"><template v-if="one(g)"><label class="in"><span>{{ expr(g) }}</span><input v-model.number="vals[i][0]" type="number" inputmode="numeric" :min="g.dice.length" :max="g.dice.reduce((a, b) => a + b, 0)" aria-label="Total of the dice" @keydown.enter="ready && send(true)"></label></template><template v-else><label v-for="(d, j) in g.dice" :key="j" class="in"><span>d{{ d }}</span><input v-model.number="vals[i][j]" type="number" inputmode="numeric" min="1" :max="d" :aria-label="`d${d}`" @keydown.enter="ready && send(true)"></label></template></template><template v-else><Die v-for="(d, j) in g.dice.slice(0, 12)" :key="j" :d="d" :v="face(i, j, d)" :size="g.dice.length > 6 ? 46 : 70" :off="!!shown && !flick && !keep(g, shown.v[i] ?? [])[j]" /></template><span v-if="g.mod" class="mod">{{ signed(g.mod) }}</span><b v-if="shown && !flick" class="tot">{{ tot(g, shown.v[i] ?? []) }}</b></div>
    <footer v-if="!shown"><button v-if="!typing" class="btn primary big" :disabled="busy" @click="send(false)">Throw</button><button v-else class="btn primary big" :disabled="busy || !ready" @click="send(true)">That is what fell</button><button v-if="cur.back" class="btn quiet" @click="back">Take it back</button><span class="grow" /><div class="md"><button :class="{ on: app.prefs.dice === 'press' }" @click="setDice('press')">Press</button><button v-if="gs?.set.handDice !== false" :class="{ on: app.prefs.dice === 'type' }" @click="setDice('type')">Real dice</button><button :class="{ on: app.prefs.dice === 'auto' }" @click="setDice('auto'); send(false)">Automatic</button></div></footer></section></div></template>
<style scoped>
.rc{display:grid;justify-items:center;gap:6px;pointer-events:none}.rc>*{pointer-events:auto}.ot{display:grid;gap:3px;justify-items:center}.ot span{background:var(--navy);padding:4px 12px;display:flex;gap:10px;align-items:center;font-size:15.5px}.card{width:min(500px,94vw);animation:rise .14s;border-top:8px solid var(--spot)}header{padding:12px 20px 4px;position:relative;padding-right:96px}header small{font-size:15px;color:var(--ink2)}h3{font-size:28px}header p{margin:3px 0 0;font-size:16px}.dc{position:absolute;right:18px;top:12px;font:800 46px/.8 var(--serif);text-align:center}.dc i{display:block;font:400 14px/1 var(--ui);font-style:normal;margin-top:7px;color:var(--ink2)}
.grp{display:flex;flex-wrap:wrap;align-items:center;gap:7px;padding:8px 20px}.gl{width:100%;font-size:15px;color:var(--ink2);margin-bottom:-3px}.mod{font:700 31px/1 var(--serif);margin-left:3px}.tot{font:800 54px/.8 var(--serif);margin-left:auto}.in{display:flex;align-items:center;gap:7px;font-weight:500}.in input{width:74px;font:800 32px/1 var(--serif);text-align:center;background:#fff;border:2px solid var(--ink);padding:5px 2px;color:var(--ink);-moz-appearance:textfield}.in input::-webkit-inner-spin-button{display:none}.in input:invalid{border-color:var(--bad)}
footer{display:flex;align-items:center;gap:10px;padding:8px 20px 14px;flex-wrap:wrap}.md{display:flex}.md button{font-size:15px;padding:4px 8px;color:var(--ink2);border-bottom:3px solid transparent}.md .on{color:var(--ink);border-color:var(--spot)}.done{border-top-color:var(--ink)}
@media(max-width:640px){h3{font-size:23px}.tot{font-size:42px}}
</style>
